import numpy as np

demo1_input = np.array([[7,6,7],[2,7,6],[1,2,7]])

def solve_debug(input_grid):
    center = np.array(input_grid)
    output = np.zeros((9, 9), dtype=int)

    for i in range(3):
        for j in range(3):
            dist = abs(i - 1) + abs(j - 1)

            if dist == 0:
                rot = 0
            elif dist == 1:
                if i != 1:
                    rot = -1
                else:
                    rot = 1
            else:
                rot = 2

            rotated_block = np.rot90(center, k=rot)
            output[i*3:(i+1)*3, j*3:(j+1)*3] = rotated_block
            print(f"Block ({i},{j}): rot={rot}, first_row=[{rotated_block[0].tolist()}]")

    return output

print("Building Demo 1 output:")
pred_debug = solve_debug(demo1_input)
print("\nFinal output:")
for row in pred_debug:
    print(row.tolist())

import numpy as np

demo2_center = np.array([[6,1,7],[1,6,7],[4,7,4]])
transpose_result = demo2_center.T

edge_blocks_expected = {
    "(0,1)": [[4,7,4],[1,6,7],[6,1,7]],
    "(1,0)": [[7,1,6],[7,6,1],[4,7,4]],
    "(1,2)": [[7,1,6],[7,6,1],[4,7,4]],
    "(2,1)": [[4,7,4],[1,6,7],[6,1,7]],
}

print("Demo 2 edge block analysis:")
for i in range(3):
    for j in range(3):
        if i not in [0,2] and j not in [0,2]:
            continue  # Skip non-edge positions

        key = f"({i},{j})"
        target = np.array(edge_blocks_expected[key])

        # First check regular rotation (no transpose)
        for k in range(4):
            result = np.rot90(demo2_center, k=k)
            if np.array_equal(result, target):
                print(f"✓ Block {key}: rot{k}")
                break
        else:
            # Try transpose + rotation
            for k in range(4):
                result = np.rot90(transpose_result, k=k)
                if np.array_equal(result, target):
                    print(f"✓ Block {key}: transpose+rot{k}")
                    break
            else:
                print(f"? Block {key}: NO MATCH FOUND")

# Also verify corners still use simple rotations
print("\nVerifying corner blocks use simple rotations:")
corner_blocks_expected = {
    "(0,0)": [[4,7,4],[7,6,1],[7,1,6]],
    "(0,2)": [[4,7,4],[7,6,1],[7,1,6]],
    "(2,0)": [[4,7,4],[7,6,1],[7,1,6]],
    "(2,2)": [[4,7,4],[7,6,1],[7,1,6]],
}

for i in range(3):
    for j in range(3):
        if i % 2 == 0 and j % 2 == 0:  # Corners
            key = f"({i},{j})"
            target = np.array(corner_blocks_expected[key])

            matches_found = False
            for k in range(4):
                result = np.rot90(demo2_center, k=k)
                if np.array_equal(result, target):
                    print(f"✓ Block {key}: rot{k} = {result[0].tolist()}")
                    matches_found = True
                    break

            if not matches_found:
                print(f"? Block {key}: No match!")
